css:
.ds-broadsheet { --ds-cover-bg: var(--ds-newsprint); }
.ds-broadsheet .ds-section h2, .ds-broadsheet .ds-cover-name { font-family: var(--font-display); font-weight: 700; }
.ds-broadsheet .ds-cover-name { font-family: "UnifrakturCook", serif; font-weight: 700; letter-spacing: 0; }
.ds-broadsheet .ds-eyebrow, .ds-broadsheet .ds-chip, .ds-broadsheet .t-small { font-family: "Libre Franklin", system-ui, sans-serif; }
.ds-broadsheet .ds-chip { border-radius: 0; }
.ds-broadsheet .ds-lede, .ds-broadsheet .ds-two p, .ds-broadsheet .ds-three p, .ds-broadsheet .ds-principle p, .ds-broadsheet .ds-comp-note, .ds-broadsheet .ds-motif p, .ds-broadsheet .ds-swatch-usage, .ds-broadsheet .ds-voice, .ds-broadsheet .ds-rules, .ds-broadsheet .ds-kv, .ds-broadsheet .ds-type-meta, .ds-broadsheet .ds-note p, .ds-broadsheet .ds-foot, .ds-broadsheet .ds-map { font-family: "Libre Franklin", system-ui, sans-serif; }
.ds-broadsheet .bs-paper { fill: var(--ds-newsprint); } .ds-broadsheet .bs-plate { fill: var(--ds-newsprint-raised); stroke: var(--ds-ink); stroke-width: 1; }
.ds-broadsheet .bs-masthead { font-family: "UnifrakturCook", serif; font-weight: 700; font-size: 34px; fill: var(--ds-ink); } .ds-broadsheet .bs-head { font-family: var(--font-display); font-weight: 700; font-size: 30px; fill: var(--ds-ink); } .ds-broadsheet .bs-deck { font-family: var(--font-display); font-style: italic; font-size: 12px; fill: var(--ds-ink-muted); }
.ds-broadsheet .bs-rule { stroke: var(--ds-ink); stroke-width: 2; } .ds-broadsheet .bs-rule-thin { stroke: var(--ds-ink); stroke-width: .8; } .ds-broadsheet .bs-col line { stroke: var(--ds-line); stroke-width: 2.5; }
.ds-broadsheet .bs-small { font-family: "Libre Franklin", sans-serif; font-weight: 600; font-size: 8px; letter-spacing: .1em; fill: var(--ds-ink); } .ds-broadsheet .bs-muted-fill { fill: var(--ds-ink-muted); } .ds-broadsheet .bs-red-fill { fill: var(--ds-red); }
.ds-broadsheet .bs-engrave path, .ds-broadsheet .bs-engrave circle, .ds-broadsheet .bs-engrave rect, .ds-broadsheet .bs-engrave line { fill: none; stroke: var(--ds-ink); stroke-width: 1.2; } .ds-broadsheet .bs-engrave-c { fill: var(--ds-newsprint-raised); stroke: var(--ds-ink); stroke-width: 1.2; } .ds-broadsheet .bs-tick { stroke: var(--ds-ink); stroke-width: 1.2; } .ds-broadsheet .bs-hand { stroke: var(--ds-ink); stroke-width: 2; stroke-linecap: round; } .ds-broadsheet .bs-roman { font-family: var(--font-display); font-size: 12px; fill: var(--ds-ink); } .ds-broadsheet .bs-red-wedge { fill: var(--ds-red-soft); }
.ds-broadsheet .bs-spec { fill: none; stroke: var(--ds-ink); stroke-width: 1.2; } .ds-broadsheet .bs-spec-red { fill: none; stroke: var(--ds-red); stroke-width: 1.6; } .ds-broadsheet .bs-pull-f { font-family: var(--font-display); font-weight: 700; font-size: 44px; }
.ds-broadsheet .bs-red { color: var(--ds-red); } .ds-broadsheet .bs-of { font-size: .5em; color: var(--ds-ink-muted); font-weight: 400; }
.ds-broadsheet .bs-btn { font-family: "Libre Franklin", sans-serif; font-size: 12px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; line-height: 16px; padding: 10px 16px; border: 1px solid var(--ds-ink); background: transparent; color: var(--ds-ink); cursor: pointer; }
.ds-broadsheet .bs-btn:hover { background: var(--ds-newsprint-sunk); } .ds-broadsheet .bs-btn:focus-visible { outline: 2px solid var(--ds-red); outline-offset: 2px; }
.ds-broadsheet .bs-btn-primary { background: var(--ds-red); color: var(--ds-on-red); border-color: var(--ds-red); } .ds-broadsheet .bs-btn-primary:hover { background: var(--ds-red); }
.ds-broadsheet .bs-tag { display: inline-flex; padding: 3px 8px; border: 1px solid var(--ds-ink); font-family: "Libre Franklin", sans-serif; font-size: 10px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; } .ds-broadsheet .bs-tag-red { color: var(--ds-red); border-color: var(--ds-red); } .ds-broadsheet .bs-tag-caution { color: var(--ds-caution); border-color: var(--ds-caution); }
.ds-broadsheet .bs-pull { display: grid; gap: 4px; padding: 12px 0; border-top: 2px solid var(--ds-ink); border-bottom: 1px solid var(--ds-ink); min-width: 200px; } .ds-broadsheet .bs-pull .t-small { color: var(--ds-ink-muted); max-width: 22ch; } .ds-broadsheet .ds-stats { gap: 24px; }
.ds-broadsheet .bs-box { padding: 12px 16px; border: 1px solid var(--ds-ink); font-size: 16px; line-height: 1.5; background: var(--ds-newsprint-raised); } .ds-broadsheet .bs-box strong { font-weight: 700; } .ds-broadsheet .bs-box-caution { border-left: 4px solid var(--ds-caution); background: var(--ds-caution-soft); } .ds-broadsheet .bs-box-red { border-left: 4px solid var(--ds-red); }
.ds-broadsheet .bs-plate-box { display: grid; gap: 8px; } .ds-broadsheet .bs-plate-art { border: 1px solid var(--ds-ink); background: var(--ds-newsprint-raised); padding: 12px; } .ds-broadsheet .bs-plate-art svg { display: block; width: 100%; height: auto; } .ds-broadsheet .bs-caption { color: var(--ds-ink-muted); letter-spacing: .04em; text-transform: none; font-size: 12px; line-height: 1.45; } .ds-broadsheet .bs-caption b { color: var(--ds-ink); letter-spacing: .1em; text-transform: uppercase; }
.ds-broadsheet .bs-sample { background: var(--ds-newsprint); padding: 32px 20px 48px; } .ds-broadsheet .bs-sample-in { max-width: 1100px; margin: 0 auto; }
.ds-broadsheet .bs-mast { text-align: center; margin: 0; } .ds-broadsheet .bs-double { border-top: 2px solid var(--ds-ink); border-bottom: 1px solid var(--ds-ink); height: 3px; margin: 8px 0 0; }
.ds-broadsheet .bs-dateline { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 8px; padding: 8px 0; border-bottom: 1px solid var(--ds-ink); }
.ds-broadsheet .bs-sample-grid { display: grid; gap: 32px; margin-top: 28px; } .ds-broadsheet .bs-flag { color: var(--ds-red); margin: 0 0 10px; } .ds-broadsheet .bs-sample-h { margin: 0; max-width: 14ch; } .ds-broadsheet .bs-deck-p { margin: 18px 0 0; max-width: 48ch; color: var(--ds-ink-muted); }
.ds-broadsheet .bs-columns { margin-top: 24px; column-gap: 24px; column-rule: 1px solid var(--ds-line); } .ds-broadsheet .bs-body { margin: 0 0 14px; font-size: 16px; line-height: 1.6; text-align: justify; hyphens: auto; } .ds-broadsheet .bs-dropcap { float: left; font-family: var(--font-display); font-weight: 700; font-size: 58px; line-height: .8; padding: 6px 8px 0 0; }
.ds-broadsheet .bs-aside { display: grid; gap: 20px; align-content: start; border-left: 1px solid var(--ds-line); padding-left: 24px; }
.ds-broadsheet .bs-record { border-top: 2px solid var(--ds-ink); } .ds-broadsheet .bs-record-h { margin: 8px 0 4px; } .ds-broadsheet .bs-rec-row { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; border-bottom: 1px solid var(--ds-line); font-size: 15px; } .ds-broadsheet .bs-rec-v { font-family: var(--font-display); font-weight: 700; font-variant-numeric: tabular-nums; }
.ds-broadsheet .bs-sample-bottom { display: grid; gap: 24px; margin-top: 32px; } .ds-broadsheet .bs-fig { border-top: 1px solid var(--ds-ink); padding-top: 10px; min-width: 0; }
.ds-broadsheet .bs-folio { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 8px; padding-top: 8px; color: var(--ds-ink-muted); } .ds-broadsheet .bs-sample-bottom + .bs-double { margin-top: 32px; }
@container (min-width: 760px) { .ds-broadsheet .bs-sample { padding: 48px 40px 64px; } .ds-broadsheet .bs-sample-grid { grid-template-columns: 3fr 2fr; } .ds-broadsheet .bs-columns { column-count: 2; } .ds-broadsheet .bs-sample-bottom { grid-template-columns: 1fr 1fr; } }

.ds-broadsheet { --ds-hand-ink: var(--ds-ink); --ds-hand-fill: var(--ds-red); --ds-hand-fill2: var(--ds-ink); --ds-hand-muted: var(--ds-newsprint-sunk); --ds-hand-ground: var(--ds-newsprint-raised); --ds-hand-stroke: 1.5; --ds-hand-cap: square; --ds-hand-tex: 1; --ds-hand-bg: var(--ds-newsprint);
  --ds-tpl-edge: 1px solid var(--ds-ink); --ds-tpl-radius: 0; --ds-tpl-rule: 1px solid var(--ds-ink); --ds-tpl-tile-shadow: none; --ds-slide-bg: var(--ds-newsprint-raised); --ds-slide-fg: var(--ds-ink); --ds-slide-title-bg: var(--ds-ink); --ds-slide-title-fg: var(--ds-newsprint); --ds-slide-split-a: var(--ds-red); --ds-slide-split-a-fg: var(--ds-on-red); --ds-slide-split-b: var(--ds-newsprint-sunk); --ds-slide-split-b-fg: var(--ds-ink); --ds-hero-bg: var(--ds-newsprint); --ds-tag-radius: 0; }
.ds-broadsheet .bs-masthead-lg { font-size: 46px; } .ds-broadsheet .bs-deck-sm { font-family: var(--font-display); font-size: 11px; fill: var(--ds-ink); } .ds-broadsheet .bs-dropcap-svg { font-family: var(--font-display); font-weight: 700; font-size: 34px; fill: var(--ds-ink); }
.ds-broadsheet .bs-wire-t { font-family: var(--font-mono); font-size: 11px; fill: var(--ds-ink); } .ds-broadsheet .bs-col-rule { stroke: var(--ds-line); stroke-width: 1; }
.ds-broadsheet .h-text { font-family: "Libre Franklin", sans-serif; font-weight: 600; font-size: 9px; letter-spacing: .1em; } .ds-broadsheet .h-num { font-family: var(--font-display); font-weight: 700; } .ds-broadsheet .h-tex-fill2 line { opacity: .7; }
.ds-broadsheet .ds-tpl-tag { border: 1px solid var(--ds-ink); font-family: "Libre Franklin", sans-serif; font-size: 10px; letter-spacing: .12em; background: transparent; } .ds-broadsheet .ds-tpl-tag.is-idle { color: var(--ds-ink-muted); border-color: var(--ds-line); }
.ds-broadsheet .ds-tpl-stage-top, .ds-broadsheet .ds-tpl-stage-foot, .ds-broadsheet .ds-tpl-split span { font-family: "Libre Franklin", sans-serif; font-weight: 600; }
.ds-broadsheet .ds-tpl-brand { font-family: "UnifrakturCook", serif; font-size: 26px; } .ds-broadsheet .ds-tpl-crumb, .ds-broadsheet .ds-tpl-kicker, .ds-broadsheet .ds-tpl-byline, .ds-broadsheet .ds-tpl-figure-cap, .ds-broadsheet .ds-tpl-step .t-label, .ds-broadsheet .ds-tpl-pull .t-label, .ds-broadsheet .ds-tpl-kpi .t-label, .ds-broadsheet .ds-tpl-tile .t-label { font-family: "Libre Franklin", sans-serif; }
.ds-broadsheet .ds-tpl-ed-body { text-align: justify; hyphens: auto; } .ds-broadsheet .ds-tpl-pull { border-top: 2px solid var(--ds-ink); } .ds-broadsheet .ds-tpl-pull-n { color: var(--ds-red); }
.ds-broadsheet .ds-tpl-row-meta, .ds-broadsheet .ds-tpl-delta, .ds-broadsheet .ds-tpl-feat p, .ds-broadsheet .ds-tpl-step p, .ds-broadsheet .ds-tpl-hero-sub { font-family: "Libre Franklin", system-ui, sans-serif; }
.ds-broadsheet .ds-tpl-slide-h { font-weight: 700; letter-spacing: -.01em; }
